set -o pipefail
# seq 737: deploy amendment-01 preparer (+runner hash line), dry-run entry gates, submit N22-warmpair2
ROOT=/data1/home/sunyiq/nearing2022_da
P="$ROOT/src/29_nearing2022_da_ar/scripts/prepare_warmup_target_pair.py"; R="$ROOT/src/29_nearing2022_da_ar/hpc/run_warmup_target_pair.slurm"
D="$ROOT/results/29_nearing2022_da_ar/formal_closure/diagnostics"
test "$(sha256sum "$P" | cut -c1-64)" = 31f856df60b0daacea873386880581f975480c842fae0d605a5abe4b40a1b664 || { echo "ABORT: server preparer not the expected v1 bytes"; exit 2; }
test "$(sha256sum "$R" | cut -c1-64)" = fa47f0318bd2d38e337177a70ccfbef7c536ea62a71c5773a9ec29aabe46e44e || { echo "ABORT: server runner not the expected fa47 bytes"; exit 2; }
cp -p "$P" "$P.v1-31f856df.bak"; cp -p "$R" "$R.fa47f031.bak"
echo '' | base64 -d > "$P.new" && echo '' | base64 -d > "$R.new"
test "$(sha256sum "$P.new" | cut -c1-64)" = 4cea5fc43b1fe72d3b0cd6ceae5f05f038fa64a00d0c4261a8b1b7b8a449c327 && test "$(sha256sum "$R.new" | cut -c1-64)" = 9e5d59be20c7f3431b6025529d0718b2e8506c52644c140c8d107a13f9e07fd1 || { echo "ABORT: transfer hash mismatch"; rm -f "$P.new" "$R.new"; exit 3; }
mv "$P.new" "$P"; mv "$R.new" "$R"
sha256sum "$P" "$R" "$ROOT/neuralhydrology/datasetzoo/basedataset.py"
source ~/miniconda3/etc/profile.d/conda.sh; conda activate nh_final
cd "$ROOT" && timeout 300 python - "$ROOT" "$P" "$D" <<'PY' || { echo "ABORT: deployed preparer rejects receipts"; exit 4; }
import sys, json, importlib.util
root, prep, d = sys.argv[1:4]
spec = importlib.util.spec_from_file_location("p", prep); m = importlib.util.module_from_spec(spec); spec.loader.exec_module(m)
r = m.validate_entry_gates(root, f"{root}/results/29_nearing2022_da_ar/formal_closure/warmup_target_paired_retraining_protocol.json",
                           f"{d}/author_v13_training_data_port_all531_v2", f"{d}/author_v13_warmup_isolation_all531_v2")
print("DEPLOYED_ENTRY_GATES_PASS basins", r["basins"], "current_only", r.get("current_only_warmup_targets"))
PY
for J in 202510 202511; do sacct -X -n -P -j $J --format=JobID,State,ExitCode; done
for X in control_seed0_repeat1 masked_seed0_repeat1 paired_analysis; do test ! -e "$D/warmup_pair/$X" || { echo "ABORT: $X already exists"; exit 5; }; done
N=$(squeue -u sunyiq -h -o '%j' 2>/dev/null | grep -c 'N22-warmpair2' || true)
if [ "$N" = "0" ]; then sbatch --job-name=N22-warmpair2 "$R"; else echo "N22-warmpair2 already queued ($N)"; fi
sleep 5; squeue -u sunyiq -h -o '%.14i %.16j %.9T %R' | grep -E 'N22-warmpair2' || echo "not in queue"
exit 0
